contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint unused) public payable {
        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!initReverted && minAfter == minBefore);
    }

    receive() external payable {}
}

