// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 unused) internal {
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        assertTrue(!initReverted && minAfter == minBefore);
    }

    function testFuzz_run(uint256 unused) public {
        _run(unused);
    }

    receive() external payable {}
}
